#!/usr/bin/env bash
# Makes a short MKV for the mpv view's test (app/src/adapters/mpv): 5 s of a test
# pattern, two audio tracks (English, Russian) and one English subtitle
# track, all generated by ffmpeg (no downloaded content).
#
#   dev/mpv-sample.sh /tmp/reel-sample.mkv
#   cd app && REEL_LIBMPV=/path/to/libmpv.2.dylib REEL_MPV_SAMPLE=/tmp/reel-sample.mkv \
#     cargo test -- --ignored mpv_plays --nocapture
set -euo pipefail

out="${1:?usage: $0 <out.mkv>}"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

cat > "$work/subs.srt" <<'EOF'
1
00:00:00,500 --> 00:00:02,000
A test pattern.

2
00:00:02,500 --> 00:00:04,500
Two tones play under it.
EOF

ffmpeg -loglevel error -y \
  -f lavfi -i "testsrc=duration=5:size=320x180:rate=25" \
  -f lavfi -i "sine=frequency=440:duration=5" \
  -f lavfi -i "sine=frequency=660:duration=5" \
  -i "$work/subs.srt" \
  -map 0:v -map 1:a -map 2:a -map 3:s \
  -c:v libx264 -preset ultrafast -c:a aac -c:s srt \
  -metadata:s:a:0 language=eng -metadata:s:a:1 language=rus -metadata:s:a:1 title=Dub \
  -metadata:s:s:0 language=eng \
  "$out"
echo "$out"
